package com.example.examplemod.cargo.center;

import com.example.examplemod.cargo.*;
import com.example.examplemod.city.CityManager;
import com.simibubi.create.content.trains.RailwaySavedData;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import java.util.*;

/** Only authorized objects are serialized. Pages and stock details are bounded; no chunk loading. */
public final class CenterView {
    private CenterView() {}
    public static CompoundTag snapshot(ServerPlayer actor,CompoundTag q){
        var s=actor.getServer();var requester=OwnerRef.player(actor.getUUID());var data=new CompoundTag();var all=new ArrayList<CompoundTag>();var choices=new CompoundTag();String section=q.getString("Section");data.putString("Section",section);
        var trains=CargoTrainRegistry.get(s).registrations();var points=CargoPointRegistry.get(s).points();var warehouses=CargoWarehouseRegistry.get(s).all();var lines=CargoLineRegistry.get(s).all();var live=RailwaySavedData.load(s).getTrains();
        var owners=new ListTag();ownerOption(owners,"PLAYER/"+actor.getUUID(),actor.getName().getString(),"PLAYER");var subjects=new ListTag();for(var p:s.getPlayerList().getPlayers())ownerOption(subjects,"PLAYER/"+p.getUUID(),p.getName().getString(),"PLAYER");
        for(var city:CityManager.get(s.overworld()).getCities()){ownerOption(subjects,"CITY/"+city.getId(),city.getName(),"CITY");if(city.isAdmin(actor.getUUID()))ownerOption(owners,"CITY/"+city.getId(),city.getName(),"CITY");}choices.put("Owners",owners);choices.put("Subjects",subjects);
        var nativeTrains=new ListTag();for(var train:live.values())if(actor.getUUID().equals(train.owner)&&CargoTrainRegistry.find(s,train.id).isEmpty())option(nativeTrains,train.id.toString(),train.name.getString());choices.put("NativeTrains",nativeTrains);
        var trainOptions=new ListTag();int trainCount=0;for(var t:trains){var access=CenterOperations.access(actor,"train",t.trainId());if(!CargoOwners.permits(s,requester,access))continue;trainCount++;option(trainOptions,t.trainId().toString(),t.displayName());if(!section.equals("trains")&&!section.equals("access"))continue;
            var nativeTrain=live.get(t.trainId());String station=nativeTrain==null||nativeTrain.getCurrentStation()==null?"":nativeTrain.getCurrentStation().name;var row=object(actor,t.trainId(),"train",t.displayName(),station.isEmpty()?access.owner().name(s):station,nativeTrain==null?"MISSING":nativeTrain.derailed||nativeTrain.invalid?"BLOCKED":"AVAILABLE",access);
            row.putString("CurrentStation",station);row.putString("ScheduleState",CargoSchedules.state(nativeTrain));
            row.putInt("ScheduleEntries",nativeTrain==null||nativeTrain.runtime.getSchedule()==null?0:nativeTrain.runtime.getSchedule().entries.size());
            if(nativeTrain!=null)for(var dimension:nativeTrain.getPresentDimensions()){var pos=nativeTrain.getPositionInDimension(dimension);if(pos.isPresent()){row.put("Location",new CargoInfrastructure.Location(dimension.location(),pos.get()).save());break;}}all.add(row);}
        choices.put("Trains",trainOptions);data.putInt("TrainCount",trainCount);
        var pointOptions=new ListTag();var stationOptions=new ListTag();var routerOptions=new ListTag();int pointCount=0;
        for(var p:points){var access=CenterOperations.access(actor,"point",p.id());boolean visible=CargoOwners.permits(s,requester,access)||lines.stream().anyMatch(l->CargoOwners.permits(s,requester,CargoLineRegistry.access(s,l))&&l.stops().stream().anyMatch(stop->stop.point().equals(p.id())))||warehouses.stream().anyMatch(w->w.point().equals(p.id())&&CargoWarehouseRegistry.permits(actor,w));if(!visible)continue;pointCount++;option(pointOptions,p.id().toString(),p.name());
            if(section.equals("points")||section.equals("access")){var row=object(actor,p.id(),"point",p.name(),"",p.routers().isEmpty()?"WAITING_POINT":"CONFIGURED",access);p.routers().stream().findFirst().ifPresent(r->row.put("Location",new CargoInfrastructure.Location(r.dimension(),r.pos()).save()));pointDetails(actor,p,row);all.add(row);}
            for(var binding:CargoLineRegistry.get(s).stations().entrySet())if(binding.getValue().equals(p.id())){var station=CargoRailConnections.station(s,binding.getKey());option(stationOptions,binding.getKey().toString(),station==null?p.name():p.name()+" / "+station.station().name);}}
        choices.put("Points",pointOptions);choices.put("Stations",stationOptions);choices.put("Routers",routerOptions);data.putInt("PointCount",pointCount);
        var warehouseOptions=new ListTag();int warehouseCount=0;for(var w:warehouses){if(!CargoWarehouseRegistry.permits(actor,w))continue;warehouseCount++;option(warehouseOptions,w.id().toString(),w.name());if(!section.equals("warehouses")&&!section.equals("access"))continue;
            var ticker=CargoWarehouseRegistry.ticker(s,w);var row=object(actor,w.id(),"warehouse",w.name(),"",ticker==null?"UNLOADED":"CONNECTED",CargoWarehouseRegistry.access(s,w));row.put("Location",w.ticker().save());
            row.putString("PointName",CargoPointRegistry.find(s,w.point()).map(CargoPointRegistry.Point::name).orElse(""));
            row.putString("Receiver",w.receiver()==null?"NOT_CONFIGURED":equipmentState(s,w.receiver(),com.simibubi.create.content.logistics.packager.PackagerBlockEntity.class));
            if(w.receiver()!=null)row.put("ReceiverLocation",w.receiver().save());
            if(q.hasUUID("Selected")&&q.getUUID("Selected").equals(w.id())&&ticker!=null){var stock=ticker.warehouseStock(actor,w.id());var items=new ListTag();var options=new ListTag();if(stock.isPresent()){int index=0;for(var entry:stock.get()){if(!entry.type().getHoverName().getString().toLowerCase(Locale.ROOT).contains(q.getString("StockSearch").toLowerCase(Locale.ROOT)))continue;var item=new CompoundTag();item.putString("Name",entry.type().getHoverName().getString());item.putInt("Count",entry.available());itemName(item,entry.type());item.put("Item",entry.type().copyWithCount(1).save(s.registryAccess()));items.add(item);var option=new CompoundTag();option.putString("Value",CargoFulfillment.stockKey(s,entry.type()));option.putString("Name",entry.type().getHoverName().getString());option.putInt("Count",entry.available());itemName(option,entry.type());options.add(option);if(++index>=128)break;}}row.putBoolean("StockLimited",items.size()>=128);row.put("Stock",items);row.putBoolean("StockAvailable",stock.isPresent());choices.put("Stock",options);}all.add(row);}
        choices.put("Warehouses",warehouseOptions);data.putInt("WarehouseCount",warehouseCount);
        for(var l:lines){var access=CargoLineRegistry.access(s,l);if(!CargoOwners.permits(s,requester,access)||!section.equals("lines")&&!section.equals("access"))continue;boolean connected=true;var details=new ListTag();for(int i=0;i<l.stops().size();i++){var stop=l.stops().get(i);var t=new CompoundTag();t.putString("Name",CargoPointRegistry.find(s,stop.point()).map(CargoPointRegistry.Point::name).orElse("MISSING"));var st=CargoRailConnections.station(s,stop.station());t.putString("Detail",st==null?"STATION_MISSING":st.station().name);details.add(t);if(i>0&&CargoRailConnections.path(s,l.stops().get(i-1).station(),stop.station()).isEmpty())connected=false;}
            boolean equipped=true,ready=true;for(int i=1;i<l.stops().size();i++){var a=l.stops().get(i-1);var b=l.stops().get(i);equipped &= CargoRoutePlanner.equipment(s,a.point(),a.station())&&CargoRoutePlanner.equipment(s,b.point(),b.station());ready &= CargoLineRegistry.get(s).availableTrain(s,l,requester,a.point(),b.point())!=null;}
            var row=object(actor,l.id(),"line",l.name(),"",!l.enabled()?"DISABLED":!connected?"BLOCKED":!equipped?"WAITING_POINT":!ready?"WAITING_TRAIN":"CONFIGURED",access);
            details.clear();for(var stop:l.stops()){var station=CargoRailConnections.station(s,stop.station());CenterCardData.part(details,"station",station==null?"":station.station().name,station==null?"MISSING":"CONNECTED",CargoPointRegistry.find(s,stop.point()).map(CargoPointRegistry.Point::name).orElse(""));}
            for(UUID id:new TreeSet<>(l.trains())){var train=live.get(id);CenterCardData.part(details,"train",train==null?"":train.name.getString(),CargoSchedules.state(train),"");}
            row.put("Details",details);row.putInt("StationCount",l.stops().size());row.putInt("LineTrainCount",l.trains().size());row.putString("Mode",l.mode().name());row.putLong("Tariff",l.tariff());row.putString("Terms",l.terms());row.putBoolean("Enabled",l.enabled());all.add(row);}
        var book=com.example.examplemod.economy.EconomyManager.get(actor.serverLevel()).cargo();
        if(section.equals("trade")||section.equals("access"))for(var offer:book.offers()){var access=CenterOperations.access(actor,"offer",offer.id());if(!CargoOwners.permits(s,requester,access)||!offer.active()&&!access.owner().manages(s,actor.getUUID()))continue;var warehouse=CargoWarehouseRegistry.get(s).find(offer.warehouse()).orElse(null);var row=object(actor,offer.id(),"offer",offer.itemName(),"",offer.active()?"QUEUED":"DISABLED",access);row.putLong("Price",offer.unitPrice());row.putInt("Remaining",offer.remaining());row.putString("WarehouseName",warehouse==null?"":warehouse.name());row.putString("TermsCode","stock_unreserved");itemName(row,net.minecraft.world.item.ItemStack.parseOptional(s.registryAccess(),offer.item()));if(warehouse!=null)row.put("Location",warehouse.ticker().save());all.add(row);}
        int shipmentCount=0;for(var shipment:CargoShipmentRegistry.get(s).all()){boolean visible=actor.hasPermissions(2)||shipment.owner().operates(s,actor.getUUID())||shipment.creator().equals(actor.getUUID())||warehouses.stream().anyMatch(w->w.id().equals(shipment.sourceWarehouse())&&CargoWarehouseRegistry.access(s,w).owner().operates(s,actor.getUUID()));if(!visible)continue;shipmentCount++;
            if(section.equals("shipments")){var row=CenterService.row(shipment.id(),shipment.type().getHoverName().getString(),shipment.problem(),shipment.stage().name());row.putString("Kind","shipment");row.putString("Dispatch",CargoCharters.get(s).progress(shipment.id()));row.putString("OwnerName",shipment.owner().name(s));
                itemName(row,shipment.type());row.putInt("ItemCount",shipment.quantity());
                row.putInt("Quantity",shipment.quantity());row.putInt("Packaged",shipment.packaged());row.putInt("Delivered",shipment.delivered());row.putInt("Recovered",shipment.recovered());row.putBoolean("CancellationRequested",shipment.cancellationRequested());
                row.putString("SourceName",CargoWarehouseRegistry.get(s).find(shipment.sourceWarehouse()).map(CargoWarehouseRegistry.Warehouse::name).orElse(""));
                var routeNodes=new ListTag();for(var leg:shipment.route()){var node=new CompoundTag();node.putString("Name",CargoPointRegistry.find(s,leg.from()).map(CargoPointRegistry.Point::name).orElse(""));routeNodes.add(node);}var destinationNode=new CompoundTag();destinationNode.putString("Name",CargoPointRegistry.find(s,shipment.finalPoint()).map(CargoPointRegistry.Point::name).orElse(""));routeNodes.add(destinationNode);row.put("RouteNodes",routeNodes);row.putString("DestinationName",CargoWarehouseRegistry.get(s).find(shipment.destinationWarehouse()).map(CargoWarehouseRegistry.Warehouse::name).orElse(""));
                var details=new ListTag();for(String event:shipment.history()){var t=new CompoundTag();t.putString("Name",event);details.add(t);}row.put("Details",details);var order=book.order(shipment.id()).orElse(null);
                if(order!=null){row.putString("OrderState",order.state().name());row.putLong("TotalCr",order.total());row.putBoolean("CanCancel",shipment.canCancel(order,actor.hasPermissions(2)||order.payer().manages(s,actor.getUUID())));}all.add(row);}}
        data.putInt("ShipmentCount",shipmentCount);
        if(section.equals("lines")){var network=new ListTag();for(var node:all){if(network.size()>=128)break;network.add(node.copy());}data.put("Network",network);data.putBoolean("NetworkLimited",all.size()>128);}
        String search=q.getString("Search").toLowerCase(Locale.ROOT);all.removeIf(row->!row.getString("Name").toLowerCase(Locale.ROOT).contains(search));all.sort(Comparator.comparing(r->r.getString("Name"),String.CASE_INSENSITIVE_ORDER));
        data.putInt("Total",all.size());int page=Math.max(0,Math.min(q.getInt("Page"),Math.max(0,(all.size()-1)/32)));data.putInt("Page",page);var rows=new ListTag();for(int i=page*32;i<Math.min(all.size(),page*32+32);i++)rows.add(all.get(i));data.put("Rows",rows);data.put("Choices",choices);
        CompoundTag selected=null;if(q.hasUUID("Selected"))for(var row:all)if(row.getUUID("Id").equals(q.getUUID("Selected")))selected=row;
        data.put("Forms",CenterForms.forms(section,selected));if(selected!=null)data.put("SelectedRow",selected.copy());
        if(section.equals("map"))data.put("Map",CargoMapView.snapshot(actor,q,pointOptions));
        data.putBoolean("Implemented",true);return data;
    }
    static CompoundTag object(ServerPlayer actor,UUID id,String kind,String name,String detail,String status,CargoOwners.Access access){var t=CenterService.row(id,name,detail,status);t.putString("Kind",kind);t.putBoolean("Manage",access.owner().manages(actor.getServer(),actor.getUUID()));t.putString("OwnerValue",access.owner().kind()+"/"+access.owner().id());t.putString("OwnerName",access.owner().name(actor.getServer()));t.putString("Access",access.mode().name());var allowed=new ListTag();for(UUID player:access.players())ownerOption(allowed,"PLAYER/"+player,com.example.examplemod.auth.PlayerNames.name(actor.getServer(),player),"PLAYER");for(UUID city:access.cities())ownerOption(allowed,"CITY/"+city,Optional.ofNullable(CityManager.get(actor.serverLevel()).getCity(city)).map(c->c.getName()).orElse(""),"CITY");t.put("Allowed",allowed);return t;}
    private static void ownerOption(ListTag list,String value,String name,String kind){if(list.size()>=256)return;var t=new CompoundTag();t.putString("Value",value);t.putString("Name",name);t.putString("OwnerKind",kind);list.add(t);}
    private static void itemName(CompoundTag row,net.minecraft.world.item.ItemStack item){if(!item.isEmpty()&&!item.has(net.minecraft.core.component.DataComponents.CUSTOM_NAME))row.putString("ItemKey",item.getDescriptionId());}
    private static String equipmentState(net.minecraft.server.MinecraftServer server,CargoInfrastructure.Location location,Class<?> type){var level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,location.dimension()));if(level==null||!level.hasChunkAt(location.pos()))return "UNLOADED";return type.isInstance(location.loaded(server))?"CONNECTED":"MISSING";}
    private static void pointDetails(ServerPlayer actor,CargoPointRegistry.Point point,CompoundTag row){
        var server=actor.getServer();var routers=new ListTag();var stations=new ListTag();var boundRouters=new ListTag();var boundStations=new ListTag();int automatic=0,count=0,unavailable=0;
        for(var ref:point.routers()) {var router=CargoInfrastructure.router(server,ref);if(router!=null&&router.automaticRouting())automatic++;if(router==null)unavailable++;
            String routerState=router==null?equipmentState(server,new CargoInfrastructure.Location(ref.dimension(),ref.pos()),CargoRouterBlockEntity.class):"CONNECTED";
            if(router==null&&routerState.equals("CONNECTED"))routerState="MISSING"; // A new block at the old position is not the bound instance.
            CenterCardData.part(routers,"router","",routerState,ref.pos().toShortString());option(boundRouters,ref.instanceId().toString(),ref.pos().toShortString());
            var boxLocation=new CargoInfrastructure.Location(ref.dimension(),ref.pos().above());var box=boxLocation.loaded(server);
            String boxState=box instanceof com.simibubi.create.content.logistics.packagePort.postbox.PostboxBlockEntity p?p.acceptsPackages&&CargoAddress.postboxFilter(point.id()).equals(p.getFilterString())?"CONNECTED":"NOT_CONFIGURED":equipmentState(server,boxLocation,com.simibubi.create.content.logistics.packagePort.postbox.PostboxBlockEntity.class);
            CenterCardData.part(routers,"postbox","",boxState,ref.pos().above().toShortString());}
        for(var binding:CargoLineRegistry.get(server).stations().entrySet())if(binding.getValue().equals(point.id())){count++;var station=CargoRailConnections.station(server,binding.getKey());String name=station==null?"":station.station().name;CenterCardData.part(stations,"station",name,station==null?"MISSING":"CONNECTED","");option(boundStations,binding.getKey().toString(),name.isBlank()?"—":name);}
        CenterCardData.point(row,routers,stations,point.routers().size(),count,automatic,unavailable);row.put("BoundRouters",boundRouters);row.put("BoundStations",boundStations);
    }
    static void option(ListTag list,String value,String name){if(list.size()>=256)return;var t=new CompoundTag();t.putString("Value",value);t.putString("Name",name);list.add(t);}
}
